import { loadNative } from '../mochinode/index.js';
import { MochiBuffer as Buffer } from '../mochibuffer/index.js';
import { Transform } from '../mochistream/index.js';

let native = null;
let nativeFailure = null;
try {
    native = await loadNative('mochizlib.dll');
} catch (error) {
    nativeFailure = error;
}

function toHex(value) {
    return Buffer.from(value).toString('hex');
}
function fromHex(value) {
    return Buffer.from(String(value || ''), 'hex');
}
function ensure() {
    if (native) return native;
    throw new Error(`mochizlib: native plugin unavailable: ${nativeFailure ? nativeFailure.message : 'not loaded'}`);
}

function normalizeOptions(options) {
    if (typeof options === 'number') return { level: options };
    return options && typeof options === 'object' ? options : {};
}

export function inflateSync(buf) {
    return fromHex(ensure().inflateHex(toHex(buf)));
}
export function gunzipSync(buf) {
    return fromHex(ensure().inflateHex(toHex(buf)));
}
export function unzipSync(buf) {
    return fromHex(ensure().inflateHex(toHex(buf)));
}
export function deflateSync(buf, options) {
    const level = normalizeOptions(options).level ?? 6;
    return fromHex(ensure().deflateHex(toHex(buf), Number(level)));
}

function callbackApi(syncFn) {
    return (buf, options, callback) => {
        if (typeof options === 'function') {
            callback = options;
            options = undefined;
        }
        try {
            const result = syncFn(buf, options);
            if (callback) callback(null, result);
            return result;
        } catch (error) {
            if (callback) callback(error);
            else throw error;
        }
    };
}

export const inflate = callbackApi(inflateSync);
export const gunzip = callbackApi(gunzipSync);
export const unzip = callbackApi(unzipSync);
export const deflate = callbackApi(deflateSync);

function createTransform(syncFn) {
    const chunks = [];
    return new Transform({
        transform(chunk, _encoding, callback) {
            chunks.push(Buffer.from(chunk));
            callback();
        },
        flush(callback) {
            try {
                const input = Buffer.concat(chunks);
                const output = syncFn(input);
                callback(null, output);
            } catch (error) {
                callback(error);
            }
        },
    });
}

export function createInflate(options) { return createTransform((buf) => inflateSync(buf, options)); }
export function createGunzip(options) { return createTransform((buf) => gunzipSync(buf, options)); }
export function createUnzip(options) { return createTransform((buf) => unzipSync(buf, options)); }
export function createDeflate(options) { return createTransform((buf) => deflateSync(buf, options)); }

export const isNativeReady = () => !!native;
export const nativeError = () => nativeFailure;

export default {
    inflate,
    inflateSync,
    gunzip,
    gunzipSync,
    unzip,
    unzipSync,
    deflate,
    deflateSync,
    createInflate,
    createGunzip,
    createUnzip,
    createDeflate,
    isNativeReady,
    nativeError,
};
